contracts/core/CitreaPaymentManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IProjectEscrow.sol";

/**
 * @title CitreaPaymentManager
 * @dev Enhanced payment manager for Citrea network with direct wallet withdrawals
 */
contract CitreaPaymentManager is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PLATFORM_ROLE = keccak256("PLATFORM_ROLE");
    bytes32 public constant ARBITRATOR_ROLE = keccak256("ARBITRATOR_ROLE");

    // Payment status enum
    enum PaymentStatus {
        Pending,
        Completed,
        Failed,
        Refunded,
        Disputed
    }

    // Withdrawal status enum
    enum WithdrawalStatus {
        Pending,
        Processing,
        Completed,
        Failed
    }

    // Payment structure
    struct Payment {
        uint256 id;
        address payer;
        address payee;
        uint256 amount;
        address token; // address(0) for native BTC
        PaymentStatus status;
        uint256 createdAt;
        uint256 completedAt;
        string metadata;
    }

    // Withdrawal structure
    struct Withdrawal {
        uint256 id;
        address user;
        uint256 amount;
        address token;
        WithdrawalStatus status;
        uint256 requestedAt;
        uint256 processedAt;
        string destinationAddress; // Bitcoin address for withdrawals
    }

    // Escrow structure for milestone payments
    struct MilestoneEscrow {
        uint256 id;
        uint256 projectId;
        address client;
        address freelancer;
        uint256 totalAmount;
        uint256 releasedAmount;
        address token;
        uint256[] milestoneAmounts;
        bool[] milestoneCompleted;
        uint256 createdAt;
        bool isActive;
    }

    // Counters
    uint256 private _paymentIdCounter;
    uint256 private _withdrawalIdCounter;
    uint256 private _escrowIdCounter;

    // Mappings
    mapping(uint256 => Payment) public payments;
    mapping(uint256 => Withdrawal) public withdrawals;
    mapping(uint256 => MilestoneEscrow) public milestoneEscrows;
    mapping(address => uint256[]) public userPayments;
    mapping(address => uint256[]) public userWithdrawals;
    mapping(address => uint256[]) public userEscrows;
    mapping(address => mapping(address => uint256)) public userBalances; // user => token => balance

    // Platform configuration
    uint256 public platformFeeRate; // in basis points (e.g., 250 = 2.5%)
    address public feeRecipient;
    uint256 public minimumWithdrawalAmount;
    mapping(address => bool) public supportedTokens;

    // Events
    event PaymentCreated(uint256 indexed paymentId, address indexed payer, address indexed payee, uint256 amount, address token);
    event PaymentCompleted(uint256 indexed paymentId, uint256 completedAt);
    event PaymentRefunded(uint256 indexed paymentId, uint256 refundedAt);
    event WithdrawalRequested(uint256 indexed withdrawalId, address indexed user, uint256 amount, address token, string destinationAddress);
    event WithdrawalProcessed(uint256 indexed withdrawalId, uint256 processedAt);
    event WithdrawalCompleted(uint256 indexed withdrawalId, uint256 completedAt);
    event MilestoneEscrowCreated(uint256 indexed escrowId, uint256 indexed projectId, address indexed client, address freelancer, uint256 totalAmount);
    event MilestoneReleased(uint256 indexed escrowId, uint256 milestoneIndex, uint256 amount);
    event BalanceDeposited(address indexed user, uint256 amount, address token);
    event BalanceWithdrawn(address indexed user, uint256 amount, address token);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(ARBITRATOR_ROLE, admin);

        platformFeeRate = 250; // 2.5% default fee
        feeRecipient = admin;
        minimumWithdrawalAmount = 0.001 ether; // Minimum withdrawal amount

        // Support native BTC by default
        supportedTokens[address(0)] = true;
    }

    /**
     * @dev Create a direct payment between users
     */
    function createPayment(
        address payee,
        uint256 amount,
        address token,
        string calldata metadata
    ) external payable nonReentrant returns (uint256 paymentId) {
        require(payee != address(0), "Invalid payee address");
        require(amount > 0, "Amount must be greater than 0");
        require(supportedTokens[token], "Token not supported");

        paymentId = _paymentIdCounter++;

        if (token == address(0)) {
            // Native BTC payment
            require(msg.value == amount, "Incorrect BTC amount sent");
        } else {
            // ERC20 token payment
            require(msg.value == 0, "No BTC should be sent for token payments");
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        }

        payments[paymentId] = Payment({
            id: paymentId,
            payer: msg.sender,
            payee: payee,
            amount: amount,
            token: token,
            status: PaymentStatus.Pending,
            createdAt: block.timestamp,
            completedAt: 0,
            metadata: metadata
        });

        userPayments[msg.sender].push(paymentId);
        userPayments[payee].push(paymentId);

        emit PaymentCreated(paymentId, msg.sender, payee, amount, token);
        return paymentId;
    }

    /**
     * @dev Complete a payment and transfer funds to payee
     */
    function completePayment(uint256 paymentId) external nonReentrant {
        Payment storage payment = payments[paymentId];
        require(payment.id == paymentId, "Payment does not exist");
        require(payment.status == PaymentStatus.Pending, "Payment not pending");
        require(
            msg.sender == payment.payer || 
            msg.sender == payment.payee || 
            hasRole(ARBITRATOR_ROLE, msg.sender),
            "Not authorized"
        );

        uint256 platformFee = (payment.amount * platformFeeRate) / 10000;
        uint256 payeeAmount = payment.amount - platformFee;

        payment.status = PaymentStatus.Completed;
        payment.completedAt = block.timestamp;

        // Update user balances
        userBalances[payment.payee][payment.token] += payeeAmount;
        userBalances[feeRecipient][payment.token] += platformFee;

        emit PaymentCompleted(paymentId, block.timestamp);
        emit BalanceDeposited(payment.payee, payeeAmount, payment.token);
    }

    /**
     * @dev Request withdrawal to external wallet
     */
    function requestWithdrawal(
        uint256 amount,
        address token,
        string calldata destinationAddress
    ) external nonReentrant returns (uint256 withdrawalId) {
        require(amount >= minimumWithdrawalAmount, "Amount below minimum");
        require(supportedTokens[token], "Token not supported");
        require(userBalances[msg.sender][token] >= amount, "Insufficient balance");
        require(bytes(destinationAddress).length > 0, "Invalid destination address");

        withdrawalId = _withdrawalIdCounter++;

        userBalances[msg.sender][token] -= amount;

        withdrawals[withdrawalId] = Withdrawal({
            id: withdrawalId,
            user: msg.sender,
            amount: amount,
            token: token,
            status: WithdrawalStatus.Pending,
            requestedAt: block.timestamp,
            processedAt: 0,
            destinationAddress: destinationAddress
        });

        userWithdrawals[msg.sender].push(withdrawalId);

        emit WithdrawalRequested(withdrawalId, msg.sender, amount, token, destinationAddress);
        emit BalanceWithdrawn(msg.sender, amount, token);
        return withdrawalId;
    }

    /**
     * @dev Process withdrawal (admin only)
     */
    function processWithdrawal(uint256 withdrawalId) external onlyRole(ADMIN_ROLE) {
        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        require(withdrawal.id == withdrawalId, "Withdrawal does not exist");
        require(withdrawal.status == WithdrawalStatus.Pending, "Withdrawal not pending");

        withdrawal.status = WithdrawalStatus.Processing;
        withdrawal.processedAt = block.timestamp;

        emit WithdrawalProcessed(withdrawalId, block.timestamp);
    }

    /**
     * @dev Complete withdrawal (admin only)
     */
    function completeWithdrawal(uint256 withdrawalId) external onlyRole(ADMIN_ROLE) {
        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        require(withdrawal.id == withdrawalId, "Withdrawal does not exist");
        require(withdrawal.status == WithdrawalStatus.Processing, "Withdrawal not processing");

        withdrawal.status = WithdrawalStatus.Completed;

        emit WithdrawalCompleted(withdrawalId, block.timestamp);
    }

    /**
     * @dev Create milestone-based escrow
     */
    function createMilestoneEscrow(
        uint256 projectId,
        address freelancer,
        uint256[] calldata milestoneAmounts,
        address token
    ) external payable nonReentrant returns (uint256 escrowId) {
        require(freelancer != address(0), "Invalid freelancer address");
        require(milestoneAmounts.length > 0, "No milestones provided");
        require(supportedTokens[token], "Token not supported");

        uint256 totalAmount = 0;
        for (uint256 i = 0; i < milestoneAmounts.length; i++) {
            require(milestoneAmounts[i] > 0, "Invalid milestone amount");
            totalAmount += milestoneAmounts[i];
        }

        if (token == address(0)) {
            require(msg.value == totalAmount, "Incorrect BTC amount sent");
        } else {
            require(msg.value == 0, "No BTC should be sent for token payments");
            IERC20(token).safeTransferFrom(msg.sender, address(this), totalAmount);
        }

        escrowId = _escrowIdCounter++;

        bool[] memory milestoneCompleted = new bool[](milestoneAmounts.length);

        milestoneEscrows[escrowId] = MilestoneEscrow({
            id: escrowId,
            projectId: projectId,
            client: msg.sender,
            freelancer: freelancer,
            totalAmount: totalAmount,
            releasedAmount: 0,
            token: token,
            milestoneAmounts: milestoneAmounts,
            milestoneCompleted: milestoneCompleted,
            createdAt: block.timestamp,
            isActive: true
        });

        userEscrows[msg.sender].push(escrowId);
        userEscrows[freelancer].push(escrowId);

        emit MilestoneEscrowCreated(escrowId, projectId, msg.sender, freelancer, totalAmount);
        return escrowId;
    }

    /**
     * @dev Release milestone payment
     */
    function releaseMilestone(uint256 escrowId, uint256 milestoneIndex) external nonReentrant {
        MilestoneEscrow storage escrow = milestoneEscrows[escrowId];
        require(escrow.id == escrowId, "Escrow does not exist");
        require(escrow.isActive, "Escrow not active");
        require(
            msg.sender == escrow.client || hasRole(ARBITRATOR_ROLE, msg.sender),
            "Not authorized"
        );
        require(milestoneIndex < escrow.milestoneAmounts.length, "Invalid milestone index");
        require(!escrow.milestoneCompleted[milestoneIndex], "Milestone already completed");

        uint256 milestoneAmount = escrow.milestoneAmounts[milestoneIndex];
        uint256 platformFee = (milestoneAmount * platformFeeRate) / 10000;
        uint256 freelancerAmount = milestoneAmount - platformFee;

        escrow.milestoneCompleted[milestoneIndex] = true;
        escrow.releasedAmount += milestoneAmount;

        // Update balances
        userBalances[escrow.freelancer][escrow.token] += freelancerAmount;
        userBalances[feeRecipient][escrow.token] += platformFee;

        emit MilestoneReleased(escrowId, milestoneIndex, milestoneAmount);
        emit BalanceDeposited(escrow.freelancer, freelancerAmount, escrow.token);
    }

    /**
     * @dev Get user balance for a specific token
     */
    function getUserBalance(address user, address token) external view returns (uint256) {
        return userBalances[user][token];
    }

    /**
     * @dev Get user payments
     */
    function getUserPayments(address user) external view returns (uint256[] memory) {
        return userPayments[user];
    }

    /**
     * @dev Get user withdrawals
     */
    function getUserWithdrawals(address user) external view returns (uint256[] memory) {
        return userWithdrawals[user];
    }

    /**
     * @dev Get user escrows
     */
    function getUserEscrows(address user) external view returns (uint256[] memory) {
        return userEscrows[user];
    }

    /**
     * @dev Add supported token (admin only)
     */
    function addSupportedToken(address token) external onlyRole(ADMIN_ROLE) {
        supportedTokens[token] = true;
    }

    /**
     * @dev Remove supported token (admin only)
     */
    function removeSupportedToken(address token) external onlyRole(ADMIN_ROLE) {
        supportedTokens[token] = false;
    }

    /**
     * @dev Update platform fee rate (admin only)
     */
    function updatePlatformFeeRate(uint256 newFeeRate) external onlyRole(ADMIN_ROLE) {
        require(newFeeRate <= 1000, "Fee rate too high"); // Max 10%
        platformFeeRate = newFeeRate;
    }

    /**
     * @dev Update minimum withdrawal amount (admin only)
     */
    function updateMinimumWithdrawalAmount(uint256 newAmount) external onlyRole(ADMIN_ROLE) {
        minimumWithdrawalAmount = newAmount;
    }

    /**
     * @dev Emergency withdrawal (admin only)
     */
    function emergencyWithdraw(address token, uint256 amount) external onlyRole(ADMIN_ROLE) {
        if (token == address(0)) {
            payable(msg.sender).transfer(amount);
        } else {
            IERC20(token).safeTransfer(msg.sender, amount);
        }
    }
}

contracts/core/SkillPlatform.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../interfaces/ISkillPlatform.sol";
import "../interfaces/IUserRegistry.sol";
import "../interfaces/ISkillVerification.sol";
import "../interfaces/IProjectEscrow.sol";
import "../tokens/SkillToken.sol";
import "../tokens/ReputationToken.sol";

/**
 * @title SkillPlatform
 * @dev Main contract for the Web3 Skill Platform
 */
contract SkillPlatform is ISkillPlatform, AccessControl, ReentrancyGuard {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MODERATOR_ROLE = keccak256("MODERATOR_ROLE");

    // Counter for project IDs
    uint256 private _projectIdCounter;

    // Mapping from project ID to project
    mapping(uint256 => Project) private _projects;

    // Mapping from client address to array of project IDs
    mapping(address => uint256[]) private _clientProjects;

    // Mapping from freelancer address to array of project IDs
    mapping(address => uint256[]) private _freelancerProjects;

    // References to other contracts
    IUserRegistry private _userRegistry;
    ISkillVerification private _skillVerification;
    IProjectEscrow private _projectEscrow;
    SkillToken private _skillToken;
    ReputationToken private _reputationToken;

    // Platform fee percentage (in basis points, e.g., 250 = 2.5%)
    uint256 public platformFeeRate;

    /**
     * @dev Constructor that sets up roles and references
     * @param admin Address of the admin
     * @param userRegistry Address of the UserRegistry contract
     * @param skillVerification Address of the SkillVerification contract
     * @param projectEscrow Address of the ProjectEscrow contract
     * @param skillToken Address of the SkillToken contract
     * @param reputationToken Address of the ReputationToken contract
     */
    constructor(
        address admin,
        address userRegistry,
        address skillVerification,
        address projectEscrow,
        address skillToken,
        address reputationToken
    ) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(MODERATOR_ROLE, admin);

        _userRegistry = IUserRegistry(userRegistry);
        _skillVerification = ISkillVerification(skillVerification);
        _projectEscrow = IProjectEscrow(projectEscrow);
        _skillToken = SkillToken(skillToken);
        _reputationToken = ReputationToken(reputationToken);

        platformFeeRate = 250; // 2.5% default fee
    }

    /**
     * @dev Creates a new project
     * @param _freelancer Address of the freelancer
     * @param _amount Amount to be paid for the project
     * @param _deadline Deadline for the project completion
     * @param _metadata IPFS hash or other metadata reference
     * @return projectId The ID of the created project
     */
    function createProject(
        address _freelancer,
        uint256 _amount,
        uint256 _deadline,
        string calldata _metadata
    ) external payable override nonReentrant returns (uint256 projectId) {
        require(_userRegistry.isUserRegistered(msg.sender), "SkillPlatform: client not registered");
        require(_userRegistry.isUserRegistered(_freelancer), "SkillPlatform: freelancer not registered");
        require(_amount > 0, "SkillPlatform: amount must be greater than 0");
        require(_deadline > block.timestamp, "SkillPlatform: deadline must be in the future");
        require(msg.value == _amount, "SkillPlatform: sent value does not match amount");

        projectId = _projectIdCounter++;

        Project memory project = Project({
            id: projectId,
            client: msg.sender,
            freelancer: _freelancer,
            amount: _amount,
            deadline: _deadline,
            status: ProjectStatus.Created,
            createdAt: block.timestamp,
            updatedAt: block.timestamp,
            metadata: _metadata
        });

        _projects[projectId] = project;
        _clientProjects[msg.sender].push(projectId);
        _freelancerProjects[_freelancer].push(projectId);

        // Create escrow for the project
        uint256 escrowId = _projectEscrow.createEscrow(projectId, msg.sender, _freelancer, _amount);
        
        // Fund the escrow
        _projectEscrow.fundEscrow{value: _amount}(escrowId);

        emit ProjectCreated(projectId, msg.sender, _freelancer, _amount, _deadline);
        return projectId;
    }

    /**
     * @dev Updates the status of a project
     * @param _projectId ID of the project
     * @param _status New status of the project
     */
    function updateProjectStatus(uint256 _projectId, ProjectStatus _status) external override {
        Project storage project = _projects[_projectId];
        require(project.id == _projectId, "SkillPlatform: project does not exist");
        require(
            msg.sender == project.client || msg.sender == project.freelancer || hasRole(MODERATOR_ROLE, msg.sender),
            "SkillPlatform: not authorized"
        );

        // Validate status transitions
        if (msg.sender == project.client) {
            require(
                (_status == ProjectStatus.Cancelled && project.status == ProjectStatus.Created) ||
                (_status == ProjectStatus.Completed && project.status == ProjectStatus.InProgress) ||
                (_status == ProjectStatus.Disputed),
                "SkillPlatform: invalid status transition for client"
            );
        } else if (msg.sender == project.freelancer) {
            require(
                (_status == ProjectStatus.InProgress && project.status == ProjectStatus.Created) ||
                (_status == ProjectStatus.Disputed),
                "SkillPlatform: invalid status transition for freelancer"
            );
        }

        project.status = _status;
        project.updatedAt = block.timestamp;

        emit ProjectStatusUpdated(_projectId, _status, block.timestamp);

        // Handle escrow based on status
        if (_status == ProjectStatus.Completed) {
            // Get all escrows for the project and release them
            IProjectEscrow.Escrow[] memory escrows = _projectEscrow.getProjectEscrows(_projectId);
            for (uint256 i = 0; i < escrows.length; i++) {
                if (escrows[i].status == IProjectEscrow.EscrowStatus.Funded) {
                    _projectEscrow.releaseEscrow(escrows[i].id);
                }
            }

            // Reward tokens to both parties
            _rewardTokens(project.client, project.freelancer, project.amount);
        } else if (_status == ProjectStatus.Cancelled) {
            // Get all escrows for the project and refund them
            IProjectEscrow.Escrow[] memory escrows = _projectEscrow.getProjectEscrows(_projectId);
            for (uint256 i = 0; i < escrows.length; i++) {
                if (escrows[i].status == IProjectEscrow.EscrowStatus.Funded) {
                    _projectEscrow.refundEscrow(escrows[i].id);
                }
            }
        }
    }

    /**
     * @dev Releases payment for a project
     * @param _projectId ID of the project
     */
    function releasePayment(uint256 _projectId) external override {
        Project storage project = _projects[_projectId];
        require(project.id == _projectId, "SkillPlatform: project does not exist");
        require(
            msg.sender == project.client || hasRole(MODERATOR_ROLE, msg.sender),
            "SkillPlatform: not authorized"
        );
        require(project.status == ProjectStatus.InProgress, "SkillPlatform: project not in progress");

        // Get all escrows for the project and release them
        IProjectEscrow.Escrow[] memory escrows = _projectEscrow.getProjectEscrows(_projectId);
        for (uint256 i = 0; i < escrows.length; i++) {
            if (escrows[i].status == IProjectEscrow.EscrowStatus.Funded) {
                _projectEscrow.releaseEscrow(escrows[i].id);
            }
        }

        project.status = ProjectStatus.Completed;
        project.updatedAt = block.timestamp;

        emit ProjectStatusUpdated(_projectId, ProjectStatus.Completed, block.timestamp);
        emit PaymentReleased(_projectId, project.freelancer, project.amount, block.timestamp);

        // Reward tokens to both parties
        _rewardTokens(project.client, project.freelancer, project.amount);
    }

    /**
     * @dev Creates a dispute for a project
     * @param _projectId ID of the project
     * @param _reason Reason for the dispute
     */
    function createDispute(uint256 _projectId, string calldata _reason) external override {
        Project storage project = _projects[_projectId];
        require(project.id == _projectId, "SkillPlatform: project does not exist");
        require(
            msg.sender == project.client || msg.sender == project.freelancer,
            "SkillPlatform: not authorized"
        );
        require(
            project.status == ProjectStatus.Created || project.status == ProjectStatus.InProgress,
            "SkillPlatform: project cannot be disputed"
        );

        project.status = ProjectStatus.Disputed;
        project.updatedAt = block.timestamp;

        emit ProjectStatusUpdated(_projectId, ProjectStatus.Disputed, block.timestamp);
        emit DisputeCreated(_projectId, msg.sender, _reason, block.timestamp);

        // Get all escrows for the project and mark them as disputed
        IProjectEscrow.Escrow[] memory escrows = _projectEscrow.getProjectEscrows(_projectId);
        for (uint256 i = 0; i < escrows.length; i++) {
            if (escrows[i].status == IProjectEscrow.EscrowStatus.Funded) {
                _projectEscrow.disputeEscrow(escrows[i].id, _reason);
            }
        }
    }

    /**
     * @dev Resolves a dispute for a project
     * @param _projectId ID of the project
     * @param _clientShare Percentage of the payment to be released to the client (0-100)
     * @param _freelancerShare Percentage of the payment to be released to the freelancer (0-100)
     */
    function resolveDispute(
        uint256 _projectId,
        uint8 _clientShare,
        uint8 _freelancerShare
    ) external override onlyRole(MODERATOR_ROLE) {
        Project storage project = _projects[_projectId];
        require(project.id == _projectId, "SkillPlatform: project does not exist");
        require(project.status == ProjectStatus.Disputed, "SkillPlatform: project not disputed");
        require(_clientShare + _freelancerShare <= 100, "SkillPlatform: shares must sum to 100 or less");

        // Get all escrows for the project and resolve them
        IProjectEscrow.Escrow[] memory escrows = _projectEscrow.getProjectEscrows(_projectId);
        for (uint256 i = 0; i < escrows.length; i++) {
            if (escrows[i].status == IProjectEscrow.EscrowStatus.Disputed) {
                _projectEscrow.resolveDispute(escrows[i].id, _clientShare, _freelancerShare);
            }
        }

        project.status = ProjectStatus.Completed;
        project.updatedAt = block.timestamp;

        emit ProjectStatusUpdated(_projectId, ProjectStatus.Completed, block.timestamp);

        // Reward tokens based on the resolution
        if (_freelancerShare > 0) {
            uint256 freelancerAmount = (project.amount * _freelancerShare) / 100;
            _rewardTokens(project.client, project.freelancer, freelancerAmount);
        }
    }

    /**
     * @dev Gets a project by ID
     * @param _projectId ID of the project
     * @return Project struct
     */
    function getProject(uint256 _projectId) external view override returns (Project memory) {
        require(_projects[_projectId].id == _projectId, "SkillPlatform: project does not exist");
        return _projects[_projectId];
    }

    /**
     * @dev Gets all projects for a client
     * @param _client Address of the client
     * @return Array of Project structs
     */
    function getClientProjects(address _client) external view override returns (Project[] memory) {
        uint256[] memory projectIds = _clientProjects[_client];
        Project[] memory clientProjects = new Project[](projectIds.length);

        for (uint256 i = 0; i < projectIds.length; i++) {
            clientProjects[i] = _projects[projectIds[i]];
        }

        return clientProjects;
    }

    /**
     * @dev Gets all projects for a freelancer
     * @param _freelancer Address of the freelancer
     * @return Array of Project structs
     */
    function getFreelancerProjects(address _freelancer) external view override returns (Project[] memory) {
        uint256[] memory projectIds = _freelancerProjects[_freelancer];
        Project[] memory freelancerProjects = new Project[](projectIds.length);

        for (uint256 i = 0; i < projectIds.length; i++) {
            freelancerProjects[i] = _projects[projectIds[i]];
        }

        return freelancerProjects;
    }

    /**
     * @dev Sets the platform fee rate
     * @param _feeRate New fee rate in basis points (e.g., 250 = 2.5%)
     */
    function setPlatformFeeRate(uint256 _feeRate) external onlyRole(ADMIN_ROLE) {
        require(_feeRate <= 1000, "SkillPlatform: fee rate cannot exceed 10%");
        platformFeeRate = _feeRate;
    }

    /**
     * @dev Rewards tokens to client and freelancer after successful project completion
     * @param _client Address of the client
     * @param _freelancer Address of the freelancer
     * @param _amount Amount of the project
     */
    function _rewardTokens(address _client, address _freelancer, uint256 _amount) internal {
        // Reward SKILL tokens to both parties
        // Client gets 1% of project value in tokens
        uint256 clientTokens = (_amount * 100) / 10000; // 1% of project value
        // Freelancer gets 2% of project value in tokens
        uint256 freelancerTokens = (_amount * 200) / 10000; // 2% of project value

        _skillToken.mint(_client, clientTokens);
        _skillToken.mint(_freelancer, freelancerTokens);

        // Update reputation for freelancer
        IUserRegistry.UserProfile memory freelancerProfile = _userRegistry.getUserProfile(_freelancer);
        uint256 newReputation = freelancerProfile.reputation + 10; // Increment by 10 points
        _userRegistry.updateReputation(_freelancer, newReputation);

        // Mint reputation token for freelancer if they don't have one for this skill category
        // This is a simplified example - in a real implementation, you would determine the skill category from the project metadata
        string memory tokenURI = string(abi.encodePacked("ipfs://", _projects[_projectIdCounter - 1].metadata));
        _reputationToken.mint(_freelancer, 1, 80, tokenURI); // Skill ID 1, score 80
    }
}

contracts/core/SkillVerification.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "../interfaces/ISkillVerification.sol";
import "../interfaces/IUserRegistry.sol";

/**
 * @title SkillVerification
 * @dev Contract for verifying skills on the Web3 Skill Platform
 */
contract SkillVerification is ISkillVerification, AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant PLATFORM_ROLE = keccak256("PLATFORM_ROLE");

    // Counter for skill IDs
    uint256 private _skillIdCounter;

    // Counter for attestation IDs
    uint256 private _attestationIdCounter;

    // Mapping from skill ID to skill
    mapping(uint256 => Skill) private _skills;

    // Mapping from attestation ID to attestation
    mapping(uint256 => SkillAttestation) private _attestations;

    // Mapping from user address to array of attestation IDs
    mapping(address => uint256[]) private _userAttestations;

    // Mapping from skill ID to array of attestation IDs
    mapping(uint256 => uint256[]) private _skillAttestations;

    // Mapping from category to array of skill IDs
    mapping(string => uint256[]) private _categorySkills;

    // Reference to the UserRegistry contract
    IUserRegistry private _userRegistry;

    /**
     * @dev Constructor that sets up roles and references
     * @param admin Address of the admin
     * @param userRegistry Address of the UserRegistry contract
     */
    constructor(address admin, address userRegistry) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(VERIFIER_ROLE, admin);
        _userRegistry = IUserRegistry(userRegistry);
    }

    /**
     * @dev Adds a new skill
     * @param _name Name of the skill
     * @param _category Category of the skill
     * @param _metadata IPFS hash or other metadata reference
     * @return skillId The ID of the added skill
     */
    function addSkill(
        string calldata _name,
        string calldata _category,
        string calldata _metadata
    ) external override onlyRole(ADMIN_ROLE) returns (uint256 skillId) {
        skillId = _skillIdCounter++;

        Skill memory skill = Skill({
            id: skillId,
            name: _name,
            category: _category,
            metadata: _metadata
        });

        _skills[skillId] = skill;
        _categorySkills[_category].push(skillId);

        emit SkillAdded(skillId, _name, _category, block.timestamp);
        return skillId;
    }

    /**
     * @dev Creates a skill attestation
     * @param _skillId ID of the skill
     * @param _evidence IPFS hash or other evidence reference
     * @return attestationId The ID of the created attestation
     */
    function createSkillAttestation(
        uint256 _skillId,
        string calldata _evidence
    ) external override returns (uint256 attestationId) {
        require(_userRegistry.isUserRegistered(msg.sender), "SkillVerification: user not registered");
        require(_skills[_skillId].id == _skillId, "SkillVerification: skill does not exist");

        attestationId = _attestationIdCounter++;

        address[] memory attesters = new address[](0);

        SkillAttestation memory attestation = SkillAttestation({
            id: attestationId,
            skillId: _skillId,
            owner: msg.sender,
            attesters: attesters,
            score: 0,
            status: SkillVerificationStatus.Pending,
            evidence: _evidence,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        _attestations[attestationId] = attestation;
        _userAttestations[msg.sender].push(attestationId);
        _skillAttestations[_skillId].push(attestationId);

        emit SkillAttestationCreated(attestationId, _skillId, msg.sender, block.timestamp);
        return attestationId;
    }

    /**
     * @dev Verifies a skill attestation
     * @param _attestationId ID of the attestation
     * @param _score Score for the attestation (0-100)
     */
    function verifySkillAttestation(uint256 _attestationId, uint256 _score) external override onlyRole(VERIFIER_ROLE) {
        require(_attestations[_attestationId].id == _attestationId, "SkillVerification: attestation does not exist");
        require(_score <= 100, "SkillVerification: score must be between 0-100");

        SkillAttestation storage attestation = _attestations[_attestationId];
        
        // Add the verifier to the attesters array if not already present
        bool verifierExists = false;
        for (uint256 i = 0; i < attestation.attesters.length; i++) {
            if (attestation.attesters[i] == msg.sender) {
                verifierExists = true;
                break;
            }
        }
        
        if (!verifierExists) {
            attestation.attesters.push(msg.sender);
        }
        
        attestation.score = _score;
        attestation.status = SkillVerificationStatus.Verified;
        attestation.updatedAt = block.timestamp;

        emit SkillAttestationVerified(_attestationId, msg.sender, _score, block.timestamp);
    }

    /**
     * @dev Updates the status of a skill attestation
     * @param _attestationId ID of the attestation
     * @param _status New status of the attestation
     */
    function updateAttestationStatus(
        uint256 _attestationId,
        SkillVerificationStatus _status
    ) external override onlyRole(VERIFIER_ROLE) {
        require(_attestations[_attestationId].id == _attestationId, "SkillVerification: attestation does not exist");

        SkillAttestation storage attestation = _attestations[_attestationId];
        attestation.status = _status;
        attestation.updatedAt = block.timestamp;

        emit SkillAttestationStatusUpdated(_attestationId, _status, block.timestamp);
    }

    /**
     * @dev Gets a skill by ID
     * @param _skillId ID of the skill
     * @return Skill struct
     */
    function getSkill(uint256 _skillId) external view override returns (Skill memory) {
        require(_skills[_skillId].id == _skillId, "SkillVerification: skill does not exist");
        return _skills[_skillId];
    }

    /**
     * @dev Gets a skill attestation by ID
     * @param _attestationId ID of the attestation
     * @return SkillAttestation struct
     */
    function getSkillAttestation(uint256 _attestationId) external view override returns (SkillAttestation memory) {
        require(_attestations[_attestationId].id == _attestationId, "SkillVerification: attestation does not exist");
        return _attestations[_attestationId];
    }

    /**
     * @dev Gets all skill attestations for a user
     * @param _owner Address of the user
     * @return Array of SkillAttestation structs
     */
    function getUserSkillAttestations(address _owner) external view override returns (SkillAttestation[] memory) {
        uint256[] memory attestationIds = _userAttestations[_owner];
        SkillAttestation[] memory userAttestations = new SkillAttestation[](attestationIds.length);

        for (uint256 i = 0; i < attestationIds.length; i++) {
            userAttestations[i] = _attestations[attestationIds[i]];
        }

        return userAttestations;
    }

    /**
     * @dev Gets all skills in a category
     * @param _category Category of the skills
     * @return Array of Skill structs
     */
    function getSkillsByCategory(string calldata _category) external view override returns (Skill[] memory) {
        uint256[] memory skillIds = _categorySkills[_category];
        Skill[] memory categorySkills = new Skill[](skillIds.length);

        for (uint256 i = 0; i < skillIds.length; i++) {
            categorySkills[i] = _skills[skillIds[i]];
        }

        return categorySkills;
    }

    /**
     * @dev Checks if a user has a verified skill
     * @param _owner Address of the user
     * @param _skillId ID of the skill
     * @return bool indicating if the user has the verified skill
     */
    function hasVerifiedSkill(address _owner, uint256 _skillId) external view override returns (bool) {
        uint256[] memory attestationIds = _userAttestations[_owner];

        for (uint256 i = 0; i < attestationIds.length; i++) {
            SkillAttestation memory attestation = _attestations[attestationIds[i]];
            if (attestation.skillId == _skillId && attestation.status == SkillVerificationStatus.Verified) {
                return true;
            }
        }

        return false;
    }

    /**
     * @dev Gets all attestations for a skill
     * @param _skillId ID of the skill
     * @return Array of SkillAttestation structs
     */
    function getSkillAttestations(uint256 _skillId) external view returns (SkillAttestation[] memory) {
        require(_skills[_skillId].id == _skillId, "SkillVerification: skill does not exist");

        uint256[] memory attestationIds = _skillAttestations[_skillId];
        SkillAttestation[] memory skillAttestations = new SkillAttestation[](attestationIds.length);

        for (uint256 i = 0; i < attestationIds.length; i++) {
            skillAttestations[i] = _attestations[attestationIds[i]];
        }

        return skillAttestations;
    }
}

contracts/core/UserRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "../interfaces/IUserRegistry.sol";

/**
 * @title UserRegistry
 * @dev Contract for managing user profiles on the Web3 Skill Platform
 */
contract UserRegistry is IUserRegistry, AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant PLATFORM_ROLE = keccak256("PLATFORM_ROLE");

    // Mapping from user address to user profile
    mapping(address => UserProfile) private _userProfiles;

    // Mapping from role to array of user addresses
    mapping(UserRole => address[]) private _usersByRole;

    // Array of all registered users
    address[] private _allUsers;

    /**
     * @dev Constructor that sets up roles
     * @param admin Address of the admin
     */
    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(VERIFIER_ROLE, admin);
    }

    /**
     * @dev Registers a new user
     * @param _role Role of the user
     * @param _metadata IPFS hash or other metadata reference
     */
    function registerUser(UserRole _role, string calldata _metadata) external override {
        require(!isUserRegistered(msg.sender), "UserRegistry: user already registered");

        UserProfile memory profile = UserProfile({
            userAddress: msg.sender,
            role: _role,
            verificationStatus: VerificationStatus.Unverified,
            metadata: _metadata,
            reputation: 0,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        _userProfiles[msg.sender] = profile;
        _usersByRole[_role].push(msg.sender);
        _allUsers.push(msg.sender);

        emit UserRegistered(msg.sender, _role, block.timestamp);
    }

    /**
     * @dev Updates a user's profile
     * @param _metadata IPFS hash or other metadata reference
     */
    function updateProfile(string calldata _metadata) external override {
        require(isUserRegistered(msg.sender), "UserRegistry: user not registered");

        UserProfile storage profile = _userProfiles[msg.sender];
        profile.metadata = _metadata;
        profile.updatedAt = block.timestamp;
    }

    /**
     * @dev Updates a user's verification status
     * @param _userAddress Address of the user
     * @param _status New verification status
     */
    function updateVerificationStatus(address _userAddress, VerificationStatus _status) external override onlyRole(VERIFIER_ROLE) {
        require(isUserRegistered(_userAddress), "UserRegistry: user not registered");

        UserProfile storage profile = _userProfiles[_userAddress];
        profile.verificationStatus = _status;
        profile.updatedAt = block.timestamp;

        emit VerificationStatusUpdated(_userAddress, _status, block.timestamp);
    }

    /**
     * @dev Updates a user's reputation
     * @param _userAddress Address of the user
     * @param _reputation New reputation score
     */
    function updateReputation(address _userAddress, uint256 _reputation) external override onlyRole(PLATFORM_ROLE) {
        require(isUserRegistered(_userAddress), "UserRegistry: user not registered");

        UserProfile storage profile = _userProfiles[_userAddress];
        uint256 oldReputation = profile.reputation;
        profile.reputation = _reputation;
        profile.updatedAt = block.timestamp;

        emit ReputationUpdated(_userAddress, oldReputation, _reputation, block.timestamp);
    }

    /**
     * @dev Gets a user's profile
     * @param _userAddress Address of the user
     * @return UserProfile struct
     */
    function getUserProfile(address _userAddress) external view override returns (UserProfile memory) {
        require(isUserRegistered(_userAddress), "UserRegistry: user not registered");
        return _userProfiles[_userAddress];
    }

    /**
     * @dev Checks if a user is registered
     * @param _userAddress Address of the user
     * @return bool indicating if the user is registered
     */
    function isUserRegistered(address _userAddress) public view override returns (bool) {
        return _userProfiles[_userAddress].userAddress != address(0);
    }

    /**
     * @dev Checks if a user is verified
     * @param _userAddress Address of the user
     * @return bool indicating if the user is verified
     */
    function isUserVerified(address _userAddress) external view override returns (bool) {
        require(isUserRegistered(_userAddress), "UserRegistry: user not registered");
        return _userProfiles[_userAddress].verificationStatus == VerificationStatus.Verified;
    }

    /**
     * @dev Gets all users with a specific role
     * @param _role Role of the users to get
     * @return Array of user addresses
     */
    function getUsersByRole(UserRole _role) external view override returns (address[] memory) {
        return _usersByRole[_role];
    }

    /**
     * @dev Gets all registered users
     * @return Array of user addresses
     */
    function getAllUsers() external view returns (address[] memory) {
        return _allUsers;
    }

    /**
     * @dev Gets the total number of registered users
     * @return uint256 Total number of users
     */
    function getTotalUsers() external view returns (uint256) {
        return _allUsers.length;
    }
}

contracts/escrow/ProjectEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../interfaces/IProjectEscrow.sol";

/**
 * @title ProjectEscrow
 * @dev Contract for managing escrow payments for projects on the Web3 Skill Platform
 */
contract ProjectEscrow is IProjectEscrow, AccessControl, ReentrancyGuard {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PLATFORM_ROLE = keccak256("PLATFORM_ROLE");
    bytes32 public constant ARBITRATOR_ROLE = keccak256("ARBITRATOR_ROLE");

    // Counter for escrow IDs
    uint256 private _escrowIdCounter;

    // Mapping from escrow ID to escrow
    mapping(uint256 => Escrow) private _escrows;

    // Mapping from project ID to array of escrow IDs
    mapping(uint256 => uint256[]) private _projectEscrows;

    // Mapping from client address to array of escrow IDs
    mapping(address => uint256[]) private _clientEscrows;

    // Mapping from freelancer address to array of escrow IDs
    mapping(address => uint256[]) private _freelancerEscrows;

    // Platform fee percentage (in basis points, e.g., 250 = 2.5%)
    uint256 public platformFeeRate;

    // Address where platform fees are sent
    address public feeRecipient;

    /**
     * @dev Constructor that sets up roles and fee configuration
     * @param admin Address of the admin
     */
    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(ARBITRATOR_ROLE, admin);
        
        platformFeeRate = 250; // 2.5% default fee
        feeRecipient = admin; // Admin receives fees by default
    }

    /**
     * @dev Creates a new escrow
     * @param _projectId ID of the project
     * @param _client Address of the client
     * @param _freelancer Address of the freelancer
     * @param _amount Amount to be escrowed
     * @return escrowId The ID of the created escrow
     */
    function createEscrow(
        uint256 _projectId,
        address _client,
        address _freelancer,
        uint256 _amount
    ) external override onlyRole(PLATFORM_ROLE) returns (uint256 escrowId) {
        require(_client != address(0), "ProjectEscrow: invalid client address");
        require(_freelancer != address(0), "ProjectEscrow: invalid freelancer address");
        require(_amount > 0, "ProjectEscrow: amount must be greater than 0");

        escrowId = _escrowIdCounter++;

        Escrow memory escrow = Escrow({
            id: escrowId,
            projectId: _projectId,
            client: _client,
            freelancer: _freelancer,
            amount: _amount,
            status: EscrowStatus.Created,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        _escrows[escrowId] = escrow;
        _projectEscrows[_projectId].push(escrowId);
        _clientEscrows[_client].push(escrowId);
        _freelancerEscrows[_freelancer].push(escrowId);

        emit EscrowCreated(escrowId, _projectId, _client, _freelancer, _amount, block.timestamp);
        return escrowId;
    }

    /**
     * @dev Funds an escrow
     * @param _escrowId ID of the escrow
     */
    function fundEscrow(uint256 _escrowId) external payable override nonReentrant {
        Escrow storage escrow = _escrows[_escrowId];
        require(escrow.id == _escrowId, "ProjectEscrow: escrow does not exist");
        require(escrow.status == EscrowStatus.Created, "ProjectEscrow: escrow not in Created status");
        require(msg.sender == escrow.client, "ProjectEscrow: only client can fund escrow");
        require(msg.value == escrow.amount, "ProjectEscrow: incorrect funding amount");

        escrow.status = EscrowStatus.Funded;
        escrow.updatedAt = block.timestamp;

        emit EscrowFunded(_escrowId, msg.value, block.timestamp);
    }

    /**
     * @dev Releases an escrow to the freelancer
     * @param _escrowId ID of the escrow
     */
    function releaseEscrow(uint256 _escrowId) external override nonReentrant {
        Escrow storage escrow = _escrows[_escrowId];
        require(escrow.id == _escrowId, "ProjectEscrow: escrow does not exist");
        require(escrow.status == EscrowStatus.Funded, "ProjectEscrow: escrow not in Funded status");
        require(
            msg.sender == escrow.client || hasRole(PLATFORM_ROLE, msg.sender),
            "ProjectEscrow: only client or platform can release escrow"
        );

        escrow.status = EscrowStatus.Released;
        escrow.updatedAt = block.timestamp;

        // Calculate platform fee
        uint256 fee = (escrow.amount * platformFeeRate) / 10000;
        uint256 freelancerAmount = escrow.amount - fee;

        // Transfer funds
        (bool feeSuccess, ) = feeRecipient.call{value: fee}("");
        require(feeSuccess, "ProjectEscrow: fee transfer failed");

        (bool freelancerSuccess, ) = escrow.freelancer.call{value: freelancerAmount}("");
        require(freelancerSuccess, "ProjectEscrow: freelancer transfer failed");

        emit EscrowReleased(_escrowId, escrow.freelancer, freelancerAmount, block.timestamp);
    }

    /**
     * @dev Refunds an escrow to the client
     * @param _escrowId ID of the escrow
     */
    function refundEscrow(uint256 _escrowId) external override nonReentrant {
        Escrow storage escrow = _escrows[_escrowId];
        require(escrow.id == _escrowId, "ProjectEscrow: escrow does not exist");
        require(escrow.status == EscrowStatus.Funded, "ProjectEscrow: escrow not in Funded status");
        require(
            msg.sender == escrow.freelancer || hasRole(PLATFORM_ROLE, msg.sender) || hasRole(ARBITRATOR_ROLE, msg.sender),
            "ProjectEscrow: only freelancer, platform, or arbitrator can refund escrow"
        );

        escrow.status = EscrowStatus.Refunded;
        escrow.updatedAt = block.timestamp;

        // Transfer funds back to client
        (bool success, ) = escrow.client.call{value: escrow.amount}("");
        require(success, "ProjectEscrow: refund transfer failed");

        emit EscrowRefunded(_escrowId, escrow.client, escrow.amount, block.timestamp);
    }

    /**
     * @dev Creates a dispute for an escrow
     * @param _escrowId ID of the escrow
     * @param _reason Reason for the dispute
     */
    function disputeEscrow(uint256 _escrowId, string calldata _reason) external override {
        Escrow storage escrow = _escrows[_escrowId];
        require(escrow.id == _escrowId, "ProjectEscrow: escrow does not exist");
        require(escrow.status == EscrowStatus.Funded, "ProjectEscrow: escrow not in Funded status");
        require(
            msg.sender == escrow.client || msg.sender == escrow.freelancer,
            "ProjectEscrow: only client or freelancer can dispute escrow"
        );

        escrow.status = EscrowStatus.Disputed;
        escrow.updatedAt = block.timestamp;

        emit EscrowDisputed(_escrowId, msg.sender, _reason, block.timestamp);
    }

    /**
     * @dev Resolves a dispute for an escrow
     * @param _escrowId ID of the escrow
     * @param _clientShare Percentage of the payment to be released to the client (0-100)
     * @param _freelancerShare Percentage of the payment to be released to the freelancer (0-100)
     */
    function resolveDispute(
        uint256 _escrowId,
        uint8 _clientShare,
        uint8 _freelancerShare
    ) external override onlyRole(ARBITRATOR_ROLE) nonReentrant {
        Escrow storage escrow = _escrows[_escrowId];
        require(escrow.id == _escrowId, "ProjectEscrow: escrow does not exist");
        require(escrow.status == EscrowStatus.Disputed, "ProjectEscrow: escrow not in Disputed status");
        require(_clientShare + _freelancerShare <= 100, "ProjectEscrow: shares must sum to 100 or less");

        escrow.status = EscrowStatus.Released;
        escrow.updatedAt = block.timestamp;

        // Calculate amounts
        uint256 clientAmount = (escrow.amount * _clientShare) / 100;
        uint256 freelancerAmount = (escrow.amount * _freelancerShare) / 100;
        uint256 platformFee = escrow.amount - clientAmount - freelancerAmount;

        // Transfer funds
        if (clientAmount > 0) {
            (bool clientSuccess, ) = escrow.client.call{value: clientAmount}("");
            require(clientSuccess, "ProjectEscrow: client transfer failed");
            emit EscrowRefunded(_escrowId, escrow.client, clientAmount, block.timestamp);
        }

        if (freelancerAmount > 0) {
            (bool freelancerSuccess, ) = escrow.freelancer.call{value: freelancerAmount}("");
            require(freelancerSuccess, "ProjectEscrow: freelancer transfer failed");
            emit EscrowReleased(_escrowId, escrow.freelancer, freelancerAmount, block.timestamp);
        }

        if (platformFee > 0) {
            (bool feeSuccess, ) = feeRecipient.call{value: platformFee}("");
            require(feeSuccess, "ProjectEscrow: fee transfer failed");
        }
    }

    /**
     * @dev Gets an escrow by ID
     * @param _escrowId ID of the escrow
     * @return Escrow struct
     */
    function getEscrow(uint256 _escrowId) external view override returns (Escrow memory) {
        require(_escrows[_escrowId].id == _escrowId, "ProjectEscrow: escrow does not exist");
        return _escrows[_escrowId];
    }

    /**
     * @dev Gets all escrows for a project
     * @param _projectId ID of the project
     * @return Array of Escrow structs
     */
    function getProjectEscrows(uint256 _projectId) external view override returns (Escrow[] memory) {
        uint256[] memory escrowIds = _projectEscrows[_projectId];
        Escrow[] memory projectEscrows = new Escrow[](escrowIds.length);

        for (uint256 i = 0; i < escrowIds.length; i++) {
            projectEscrows[i] = _escrows[escrowIds[i]];
        }

        return projectEscrows;
    }

    /**
     * @dev Gets all escrows for a client
     * @param _client Address of the client
     * @return Array of Escrow structs
     */
    function getClientEscrows(address _client) external view override returns (Escrow[] memory) {
        uint256[] memory escrowIds = _clientEscrows[_client];
        Escrow[] memory clientEscrows = new Escrow[](escrowIds.length);

        for (uint256 i = 0; i < escrowIds.length; i++) {
            clientEscrows[i] = _escrows[escrowIds[i]];
        }

        return clientEscrows;
    }

    /**
     * @dev Gets all escrows for a freelancer
     * @param _freelancer Address of the freelancer
     * @return Array of Escrow structs
     */
    function getFreelancerEscrows(address _freelancer) external view override returns (Escrow[] memory) {
        uint256[] memory escrowIds = _freelancerEscrows[_freelancer];
        Escrow[] memory freelancerEscrows = new Escrow[](escrowIds.length);

        for (uint256 i = 0; i < escrowIds.length; i++) {
            freelancerEscrows[i] = _escrows[escrowIds[i]];
        }

        return freelancerEscrows;
    }

    /**
     * @dev Sets the platform fee rate
     * @param _feeRate New fee rate in basis points (e.g., 250 = 2.5%)
     */
    function setPlatformFeeRate(uint256 _feeRate) external onlyRole(ADMIN_ROLE) {
        require(_feeRate <= 1000, "ProjectEscrow: fee rate cannot exceed 10%");
        platformFeeRate = _feeRate;
    }

    /**
     * @dev Sets the fee recipient address
     * @param _feeRecipient New fee recipient address
     */
    function setFeeRecipient(address _feeRecipient) external onlyRole(ADMIN_ROLE) {
        require(_feeRecipient != address(0), "ProjectEscrow: invalid fee recipient address");
        feeRecipient = _feeRecipient;
    }
}

